  ui_story_30020401_27_dialog_content = "Sepertinya insiden ini hanya bisa diselesaikan dengan mengandalkan kemampuanmu... walaupun tak banyak yang bisa kulakukan, aku akan tetap bersamamu hingga akhir.",
