  ui_story_30020401_41_dialog_content = "Aku pernah mendengar kesimpulan serupa sebelumnya. Yang perlu kita lakukan sekarang adalah menemukan beberapa bukti yang tak terbantahkan.",
  ui_story_30020401_42_dialog_content = "Apa kamu menemukan hal yang menarik perhatian di ruangan-ruangan?",
  ui_story_30020401_43_dialog_content = "Ya, ada beberapa jejak abu-abu di sepraiku.",
  ui_story_30020401_44_dialog_content = "Apakah kamu merasakan sesuatu dari jejak ini?",
  ui_story_30020401_45_dialog_content = "Meskipun hanya ada sedikit jejak, aku merasakan bahwa itu adalah tanah.",
  ui_story_30020401_46_dialog_content = "<size=45>Madam, kau tidak bersama kami selama kunjungan kami di Illumina sebelumnya, 'kan?</size>",
  ui_story_30020401_47_dialog_content = "Aku harus menghadiri <color=#FFB400>pertemuan Legion Commander</color> saat berada di Illumina. Maaf aku tidak bisa bersama kalian.",
  ui_story_30020401_48_dialog_content = "Kuharap kamu bisa menyajikan semua informasi yang kamu peroleh dari kemampuan psikismu. Ini akan membantumu mengetahui apa yang terjadi.",
  ui_story_30020401_49_dialog_content = "Karena kau sudah mengetahui insiden ini, ayo kita simpulkan saja.",
  ui_story_30020401_50_dialog_content = "Orang yang meninggalkan catatan untukmu adalah...",
  ui_story_30020401_X50_dialog_content = "Wrath.",
  ui_story_30020401_51_option_content = "Apa? Apakah aku melewatkan sesuatu?",
  ui_story_30020401_52_dialog_content = "Kamu tidak melewatkan apa pun, dan semua yang kamu sebutkan itu tepat, kecuali karakteristik dari insiden ini.",
  ui_story_30020401_53_option_content = "Tunggu, kenapa kamu tidak memberitahuku sebelumnya?",
  ui_story_30020401_54_dialog_content = "Aku tak bermaksud buruk, dan aku tak mencoba melindungi teman Illumina-ku. Aku hanya ingin tahu pendapatmu untuk menghindari kesalahpahaman.",
  ui_story_30020401_55_dialog_content = "Alasan kesimpulanku sederhana. Aku bisa langsung tahu bahwa ini adalah tulisan tangan Wrath.",
  ui_story_30020401_56_dialog_content = "Jangan khawatir, dia bukan orang jahat dan tidak akan menjadi ancaman bagi keselamatanmu.",
  ui_story_30020401_57_dialog_content = "Jika kamu tidak ingin bertemu dengannya, aku bisa mewakilimu untuk menolak undangannya.",
  ui_story_30020401_58_dialog_content = "Alasan aku tidak segera mengatakan yang sebenarnya kepadamu adalah karena kudengar kamu memiliki <color=#FFB400>kemampuan psikis spesial</color> dan aku ingin mengambil kesempatan ini untuk menyelidikinya.",
  ui_story_30020401_59_dialog_content = "Selain itu, aku bisa mengerti mengapa kamu bisa berpikir bahwa aku terlibat dengan ini karena aku memang berkaitan dengan catatan ini.",
  ui_story_30020401_60_dialog_content = "Pada pertemuan internal Illumina sebelumnya, aku tahu ada seseorang yang merobek halaman dari buku catatan pertemuanku saat aku pergi.",
  ui_story_30020401_61_dialog_content = "Terima kasih telah memberiku surat ini untuk mengungkap pelakunya. Aku berutang padamu.",
  ui_story_30020401_62_dialog_content = "Sayangnya, ini bukan insiden besar, tapi aku senang bisa menghabiskan waktu bersamamu.",
  ui_story_30020401_63_dialog_content = "Jika kamu membutuhkan bantuanku, hubungi aku. Apa pun yang terjadi, aku akan berusaha sebaik mungkin untuk membantumu.",
  ui_story_30330503_1_dialog_content = "Hei, PlayerName! Sebelah sini!",
  ui_story_30330503_2_dialog_content = "Ada apa?",
  ui_story_30330503_3_dialog_content = "Aku ingin kamu mengajak Commander Hiiro berkeliling di Colossus.",
  ui_story_30330503_4_dialog_content = "Berkeliling?",
  ui_story_30330503_5_dialog_content = "Iya. Meskipun dia terlihat seperti tahu segalanya, ini adalah pertama kalinya dia berada di dalam Colossus.",
  ui_story_30330503_6_dialog_content = "Sungguh?",
  ui_story_30330503_7_dialog_content = "Kupikir dia sudah pernah melihatnya karena dia berpangkat sangat tinggi...",
  ui_story_30330503_8_dialog_content = "Sepertinya belum. Commander Hiiro mungkin hanya 6-7 tahun lebih tua dariku.",
  ui_story_30330503_x8_dialog_content = [[
Kecuali dia pernah melihat Colossus ketika masih sangat muda.
Sepertinya belum ada orang yang melihat Colossus yang berfungsi setelah peristiwa keji itu.]],
  ui_story_30330503_9_dialog_content = "Karenanya, aku sangat bersemangat pada saat itu!",
  ui_story_30330503_10_dialog_content = "Aku mengerti. Aku akan menemuinya sekarang.",
  ui_story_30330503_11_dialog_content = "Terima kasih. Maksudku, tak ada yang tahu tentang Colossus ini lebih baik darimu.",
  ui_story_30330503_12_dialog_content = "Berdasarkan apa yang dikatakan Vice, Hiiro seharusnya ada di sekitar sini.",
  ui_story_30330503_13_dialog_content = "Ah, aku melihatnya.",
  ui_story_30330503_14_dialog_content = "Kamu rupanya.",
  ui_story_30330503_15_dialog_content = "Ada apa?",
  ui_story_30330503_16_dialog_content = "Hmm...",
  ui_story_30330503_17_dialog_content = "(Respons yang dingin...)",
  ui_story_30330503_18_dialog_content = "Tidak ada. Aku hanya ingin tahu apakah kamu bosan saat ini.",
  ui_story_30330503_19_dialog_content = "Kamu ingin jalan-jalan di Colossus bersamaku?",
  ui_story_30330503_20_dialog_content = "Aku bisa menunjukkan tiap ruangan sambil jalan.",
  ui_story_30330503_21_dialog_content = "Aku sudah berkeliling.",
  ui_story_30330503_22_dialog_content = "Apa?...",
  ui_story_30330503_23_dialog_content = "Jangan buat aku mengulang ucapanku.",
  ui_story_30330503_24_dialog_content = "Oh, b-baiklah...",
  ui_story_30330503_25_dialog_content = "(Vice tidak memberitahuku tentang ini!)",
  ui_story_30330503_26_dialog_content = "(Sepertinya dia bahkan lebih tidak sabaran dari yang aku bayangkan.)",
  ui_story_30330503_27_dialog_content = "(Apakah dia tertarik pada Soroz?)",
  ui_story_30330503_28_dialog_content = "Tak apa, aku hanya akan menemanimu kalau begitu.",
  ui_story_30330503_29_dialog_content = "Hah?",
  ui_story_30330503_30_dialog_content = "Ada apa?",
  ui_story_30330503_31_dialog_content = "Oh, tidak, tak apa.",
  ui_story_30330503_32_dialog_content = "(Mengapa dia malah menemaniku?)",
  ui_story_30330503_33_dialog_content = "Ayo pergi.",
  ui_story_30330503_34_dialog_content = "Hei, tunggu aku!",
  ui_story_30330503_35_dialog_content = "Kamu benar-benar tidak sabaran.",
  ui_story_30330503_36_dialog_content = "Ini namanya bertindak dengan efisien.",
  ui_story_30330503_37_dialog_content = "Sebagai anggota dari pasukan pengintai dan bantuan Illumina Federation, aku harus selalu bisa mengambil keputusan cepat.",
  ui_story_30330503_38_dialog_content = "Penilaian seorang Legion Commander menentukan kekuatan operasional seluruh pasukan.",
  ui_story_30330503_39_option_content = "Apa itu Legion Commander?",
  ui_story_30330503_40_dialog_content = "Aku selalu ingin bertanya padamu tentang ini... Apa itu Legion Commander?",
  ui_story_30330503_41_dialog_content = "Legion Commander merupakan tulang punggung dari Illumina Federation, seorang pemimpin militer.",
  ui_story_30330503_42_dialog_content = "Sepertinya kamu bisa menganggap Illumina Federation sebagai negara militer... Tidak, menurutku belum bisa disebut sebagai negara.",
  ui_story_30330503_43_dialog_content = "Atasanku adalah Reinhardt, yang juga merupakan atasan dari tiga Legion Commander lainnya. Dia adalah pemimpin Illumina Federation yang sesungguhnya.",
  ui_story_30330503_44_dialog_content = "Dia memimpin kami semua, sedangkan kami hanya memimpin pasukan kami sendiri dan menyelesaikan tugas.",
  ui_story_30330503_45_option_content = "Tugas dari pasukan yang relevan.",
  ui_story_30330503_46_dialog_content = "Jadi, pasukanmu bertanggung jawab atas tugas pengintaian dan bantuan?",
  ui_story_30330503_47_dialog_content = "Ya, pasukanku adalah unit bersenjata ringan yang terkenal dengan mobilitasnya yang tinggi.",
  ui_story_30330503_48_dialog_content = "Ketidakpastian tindakan Eclipsite dan karakteristik wilayah Illumina Federation yang tersebar adalah dua alasan utama mengapa kita membutuhkan unit bantuan berkecepatan tinggi yang bisa memberikan bantuan kapan pun dan di mana pun.",
  ui_story_30330503_49_dialog_content = "Operasi penyelamatan ini adalah contoh yang sesuai untuk hal ini.",
  ui_story_30330503_x50_dialog_content = "Oh, begitu...",
  ui_story_30330503_50_dialog_content = "Huft. Menceritakan semua ini kepada orang luar sepertimu. Sepertinya aku terlalu lengah.",
  ui_story_30330503_51_dialog_content = "Menurutku ini bukan hal yang sangat rahasia.",
  ui_story_30330503_52_dialog_content = "Selain itu, menurutku sesekali mengobrol dengan seseorang itu menyenangkan.",
  ui_story_30330503_53_dialog_content = "Aku hanya bisa mengobrol dengan Soroz selama 17 tahun.",
  ui_story_30330503_54_dialog_content = "Maaf... Harusnya aku sudah memikirkan hal itu saat aku berbicara.",
  ui_story_30330503_55_dialog_content = "Tak perlu meminta maaf. Seperti kataku, sangat menyenangkan ada orang yang bisa diajak mengobrol.",
  ui_story_30330503_56_dialog_content = "Maafkan sikapku yang blak-blakan, tapi keterampilan berbicaramu cukup baik untuk seseorang yang seharusnya tidak terbiasa bersosialisasi.",
  ui_story_30330503_57_dialog_content = "Hah?",
  ui_story_30330503_58_dialog_content = "Agak sulit membayangkannya karena aku tidak memiliki pengalaman serupa, tapi...",
  ui_story_30330503_59_dialog_content = "Menurutku kamu berbicara dan bertingkah layaknya orang biasa.",
  ui_story_30330503_60_dialog_content = "...",
  ui_story_30330503_61_dialog_content = "Lupakan, aku seharusnya tidak membahas pengalaman hidup seseorang dengan santai begini.",
  ui_story_30330503_62_dialog_content = "Mari kita ubah topiknya, Caelestite muda.",
  ui_story_30330503_63_dialog_content = "Baiklah kalau begitu. Apa yang kamu rencanakan selanjutnya?",
  ui_story_30330503_64_dialog_content = "Untuk menyelesaikan misiku seperti biasa.",
  ui_story_30330503_65_dialog_content = "Misiku saat ini adalah kembali ke Illumina dan menyelesaikan laporan tentang insiden ini.",
  ui_story_30330503_66_dialog_content = "Jika diminta untuk memberikan bantuan dalam pertempuran apa pun, aku akan segera menyerbu ke medan perang dengan tentaraku.",
  ui_story_30330503_67_dialog_content = "Hmm? Kamu harus melakukan semua itu sendiri?",
  ui_story_30330503_68_dialog_content = "Ya, lebih efisien seperti itu.",
  ui_story_30330503_69_dialog_content = "Lagi pula, apa gunanya bantuan jika orang dengan kemampuan tempur terkuat tidak ada?",
  ui_story_30330503_70_dialog_content = "Tuntutannya sangat besar.",
  ui_story_30330503_71_dialog_content = "Tak apa. Aku sudah terbiasa dengan hal itu.",
  ui_story_30330503_72_dialog_content = "Kita harus berusaha sekuat tenaga dalam hidup yang singkat ini.",
  ui_story_30330503_73_dialog_content = "Akan terlambat pada saat kamu merasakan ajalmu mendekat.",
  ui_story_30330503_74_option_content = "Memang begitu.",
  ui_story_30330503_75_dialog_content = "Hidup di zaman ini, kita harus siap secara mental.",
  ui_story_30330503_76_dialog_content = "Sama halnya dengan bertahan hidup itu sendiri.",
  ui_story_30330503_77_dialog_content = "Jika bukan begitu, nenek moyang kita tidak akan melintasi siang dan malam yang abadi untuk mencapai tempat ini.",
  ui_story_30330503_78_dialog_content = "Tempat ini?",
  ui_story_30330503_79_dialog_content = "Aku bicara tentang daerah di sekitar Aurora. Ini adalah satu-satunya tempat yang bisa dihuni.",
  ui_story_30330503_80_dialog_content = "Hmm...",
  ui_story_30330503_81_option_content = "Jangan terlalu paksakan dirimu.",
  ui_story_30330503_82_dialog_content = "Aku tak peduli tentang itu. Bukan masalah jika aku memaksakan diri.",
  ui_story_30330503_83_dialog_content = "Manusia ditakdirkan untuk mati suatu hari nanti.",
  ui_story_30330503_84_dialog_content = "Aku sudah menyaksikan terlalu banyak kematian di medan perang.",
  ui_story_30330503_85_dialog_content = "Aku akan memikirkan saat-saat perpisahan itu bahkan saat aku mengambil jeda sejenak dari pekerjaan.",
  ui_story_30330503_86_dialog_content = "Mungkin ini takdir dari Sakura Family.",
  ui_story_30330503_87_dialog_content = "Hiiro...",
  ui_story_30330503_88_dialog_content = "Oke, cukup. Saatnya berpindah ke tugas berikutnya.",
  ui_story_30330503_89_dialog_content = "Secepat itu?",
  ui_story_30330503_90_dialog_content = "Aku membicarakanmu, bukan aku. Aku selalu sibuk dengan pekerjaan.",
  ui_story_30330503_91_dialog_content = "Jika target Schummer adalah Lumopolis, akan ada lebih banyak hal yang perlu kamu cemaskan daripada musuh-musuhmu.",
  ui_story_30330503_92_dialog_content = "Apa maksudmu?",
  ui_story_30330503_93_dialog_content = "Lihat dengan mata kepalamu sendiri.",
  ui_story_30330503_94_dialog_content = "Saatnya pergi.",
  ui_story_30330503_95_dialog_content = "Apa?... Hei!",
  ui_story_30330503_96_dialog_content = "(Dia sangat keren bahkan saat pergi. Sepertinya tidak mengherankan karena itu dia...)",
  ui_story_30330503_97_dialog_content = "<color=#e8d9bb>Setelah mengibaskan jubahnya, Hiiro pergi tanpa melihat ke belakang.</color>",
  ui_story_30330503_98_dialog_content = "<color=#e8d9bb>Aku mengamatinya saat siluet rampingnya menghilang di tikungan.</color>",
  ui_story_30330503_99_dialog_content = "<color=#e8d9bb>Hanya saat aku mengingat wajahnya, aku menyadari satu hal konsisten tentangnya selama percakapan itu berlangsung...</color>",
  ui_story_30330503_100_dialog_content = "<color=#e8d9bb>Wajah tanpa ekspresinya.</color>",
  ui_story_30020601_1_dialog_content = "Baiklah, patroli harianku hampir selesai. Tinggal memeriksa Bridge...",
  ui_story_30020601_2_dialog_content = "Bridge aman... Hmm?",
  ui_story_30020601_3_dialog_content = "Oh itu Hiiro.",
  ui_story_30020601_4_dialog_content = "Dia tampaknya zonasi keluar ...",
  ui_story_30020601_5_dialog_content = "Sepertinya baru kali ini aku melihatnya begitu... Harus kupastikan dia baik-baik saja.",
  ui_story_30020601_6_dialog_content = "Hiiro, Apakah semuanya baik-baik saja? Mengapa Anda menatap ke luar angkasa ...",
  ui_story_30020601_7_dialog_content = "...Tidak ada jawaban.",
  ui_story_30020601_8_dialog_content = "Halo? Commander Hiiro...?",
  ui_story_30020601_9_dialog_content = "Masih tidak ada respons.",
  ui_story_30020601_10_dialog_content = "<size=45>HIIRO! KAMU BAIK-BAIK SAJA, HIIRO?!</size>",
  ui_story_30020601_11_dialog_content = "...Hmm?",
  ui_story_30020601_12_dialog_content = "Oh, kamu rupanya.",
  ui_story_30020601_13_dialog_content = "Ada apa?",
  ui_story_30020601_14_dialog_content = "(Syukurlah, dia akhirnya menjawab...)",
  ui_story_30020601_15_dialog_content = "Tidak ada, sungguh... Aku melihatmu keluar zona, dan aku hanya sedikit khawatir.",
  ui_story_30020601_16_dialog_content = "Um... Apa itu... sebuah foto?",
  ui_story_30020601_17_dialog_content = "Oh, ini?",
  ui_story_30020601_18_dialog_content = "Ini aku.",
  ui_story_30020601_19_dialog_content = "Anda telah menatap foto diri Anda sendiri?",
  ui_story_30020601_20_dialog_content = "(Foto macam apa yang bisa membuat zonanya seperti itu, aku bertanya-tanya...)",
  ui_story_30020601_21_dialog_content = "(Aku sungguh ingin melihatnya...)",
  ui_story_30020601_22_dialog_content = "Anda benar-benar menjulurkan leher Anda di sana. Apakah tidak sakit?",
  ui_story_30020601_23_dialog_content = "Y-Ya, sedikit.",
  ui_story_30020601_24_dialog_content = "Ini.",
  ui_story_30020601_25_dialog_content = "Dengan seragam militer...?",
  ui_story_30020601_26_dialog_content = "Wow... Kamu terlihat lebih gagah dengan seragam!",
  ui_story_30020601_27_dialog_content = "Hmm.",
  ui_story_30020601_28_dialog_content = "Tapi... Kenapa tatapanmu kosong saat melihat foto ini?",
  ui_story_30020601_29_dialog_content = "...",
  ui_story_30020601_30_dialog_content = "(Sial, dia berhenti berbicara lagi...)",
  ui_story_30020601_31_dialog_content = "T-tidak apa-apa, aku mengerti kalau kamu tidak mau membicarakannya...",
  ui_story_30020601_32_dialog_content = "Saya bisa, jika Anda ingin tahu.",
  ui_story_30020601_33_dialog_content = "Ini dari saya <color=#FFB400>pelatihan</color> hari di pasukan pertahanan Illumina.",
  ui_story_30020601_34_dialog_content = "Sebagai calon lulusan Akademi Militer Illumina, kami telah mengatur pelatihan lapangan pertama untuk Anda.",
  ui_story_30020601_35_dialog_content = "Inti dari pelatihan Anda adalah melakukan patroli dan inspeksi di sepanjang rute patroli yang telah ditetapkan.",
  ui_story_30020601_36_dialog_content = "Anda perlu berpatroli dan membersihkan dua rute berbeda. Berhati-hatilah, ini bukan latihan lari di akademi, tapi kerja nyata!",
  ui_story_30020601_37_dialog_content = "Selain tugas patroli, Anda juga diharapkan untuk memeriksa pos pemeriksaan di sepanjang rute dan memastikan tidak ada anomali dalam sistem peringatan mereka.",
  ui_story_30020601_38_dialog_content = "Saya berkewajiban untuk mengingatkan Anda, bahwa sejumlah pos pemeriksaan ini ditemukan di area dengan aktivitas Eclipsite yang dikonfirmasi.",
  ui_story_30020601_39_dialog_content = "Karena alasan itulah...",
  ui_story_30020601_40_dialog_content = "Ini tidak ada bedanya dengan operasi militer sesungguhnya! Kalian harus membentuk dua kelompok berisi tiga orang untuk menjalankan misi!",
  ui_story_30020601_41_dialog_content = "Jika Anda menemukan sesuatu di luar kemampuan Anda, segera beri tahu atasan Anda! Sama seperti bagaimana Anda telah diajarkan!",
  ui_story_30020601_42_dialog_content = "Hiiro, kami mengandalkan Anda untuk terus mengawasi keselamatan semua orang.",
  ui_story_30020601_43_dialog_content = "Baiklah.",
  ui_story_30020601_44_dialog_content = "Ah... Aroma kebebasan!",
  ui_story_30020601_45_dialog_content = "Biarkan Eclipsites datang, saya tidak takut! Aku akan membantai semua yang menghalangi jalan kita!",
  ui_story_30020601_46_dialog_content = "Latihan lapangan kita terlalu mudah... Maksudku, bahaya macam apa yang mungkin kita temukan di sepanjang garis pertahanan kita? Apa lelucon ...",
  ui_story_30020601_47_dialog_content = "Sudah jelas bahwa tidak ada yang mau melakukan pekerjaan penjaga kasar semacam ini, jadi mereka menendangnya ke siswa akademi.",
  ui_story_30020601_48_dialog_content = "Ya, kamu benar! Ini sungguh buang-buang waktu dan energi...",
  ui_story_30020601_49_dialog_content = "Apa masalahnya, Hiiro besar? Tidak ada kata-kata bijak emas? Atau apakah keluhan orang biasa seperti kami sangat menyinggung perasaan Anda sehingga membuat Anda tidak bisa berkata-kata?",
  ui_story_30020601_50_dialog_content = "Tidak.",
  ui_story_30020601_51_dialog_content = "Ini aneh...",
  ui_story_30020601_52_dialog_content = "Tetapi melihat bahwa pelatihan kami sangat sederhana, saya yakin ...",
  ui_story_30020601_53_dialog_content = "Besar Hiiro bahkan tidak membutuhkan rekan satu tim untuk menyelesaikan misi ini. Anda dapat melakukan semuanya sendiri, bukan?",
  ui_story_30020601_54_dialog_content = "Tugas jaga, membersihkan jalan, memeriksa pesan peringatan... Hal sepele seperti ini...",
  ui_story_30020601_55_dialog_content = "Itu harus berjalan-jalan di taman untuk yang hebat dan berkuasa Hiiro, yang telah melihat pertempuran dan meraih kemenangan untuk Illumina!",
  ui_story_30020601_56_dialog_content = "Jadi?",
  ui_story_30020601_57_dialog_content = "Jadi, jika sempurna Hiiro harus menyelesaikan pekerjaan sendirian...",
  ui_story_30020601_58_dialog_content = "Dia bisa meraih lebih banyak pujian dan kejayaan untuk dirinya saat kita kembali ke akademi!",
  ui_story_30020601_59_dialog_content = "Lagi pula, bangsawan besar sepertimu tidak pernah menganggap kami rekan, 'kan?",
  ui_story_30020601_60_dialog_content = "Favorit Grand Marshal, yang bermeditasi dan melatih dirinya sendiri bahkan ketika dia sedang tidak bertugas...",
  ui_story_30020601_61_dialog_content = "Mengapa seseorang seperti Anda pernah bekerja sama dengan orang biasa seperti kami?",
  ui_story_30020601_62_dialog_content = "... Jadi ini yang kamu rasakan.",
  ui_story_30020601_63_dialog_content = "Kalau begitu, tidak apa-apa.",
  ui_story_30020601_64_dialog_content = "Dan apa artinya itu?!",
  ui_story_30020601_65_dialog_content = "Itu berarti saya akan berpatroli di salah satu dari dua rute dan menyelesaikan tugas saya sendiri.",
  ui_story_30020601_66_dialog_content = "Kalian bisa mengambil rute lainnya.",
  ui_story_30020601_67_dialog_content = "Tentukan pilihan Anda dan keluar dulu.",
  ui_story_30020601_68_dialog_content = "Kau...!",
  ui_story_30020601_69_dialog_content = "Dalam hal ini, semoga sukses dalam misi Anda, Hiiro besar! Cobalah untuk tidak mati di luar sana!",
  ui_story_30020601_70_dialog_content = "Ayo, semuanya, kita lewat sini! Perjalanan yang aman, Yang Mulia!",
  ui_story_30020601_71_dialog_content = "Selamat tinggal, dan berhati-hatilah.",
  ui_story_30020601_72_dialog_content = "Huh, dia hanyalah seorang wannabe sok dan babi kemuliaan ...",
  ui_story_30020601_73_dialog_content = "Saya mendengar bahwa dia sangat dekat dengan <color=#FFB400>Marsekal Agung</color>... Saya tidak berpikir Anda harus tumpul itu.",
  ui_story_30020601_74_dialog_content = "Jangan bilang kamu takut dengan penjilat seperti dia!",
  ui_story_30020601_75_dialog_content = "Mereka memberi kami sepeda motor untuk tugas jaga, eh? Bukan pilihan yang buruk...",
  ui_story_30020601_76_dialog_content = "Ada tiga pos pemeriksaan di sepanjang rute ini... Mari kita mulai.",
  ui_story_30020601_77_dialog_content = "Pos pemeriksaan A, semuanya aman. Sistem peringatan normal, dan tidak ada tanda-tanda aktivitas Eclipsite.",
  ui_story_30020601_78_dialog_content = "Titik periksa B... Di sana!",
  ui_story_30020601_79_dialog_content = "Hanya segelintir Eclipsites... Bukan ancaman langsung.",
  ui_story_30020601_80_dialog_content = "Pos pemeriksaan B, aman. Rute aman, dan sistem peringatan normal.",
  ui_story_30020601_81_dialog_content = "Pos pemeriksaan C, semuanya aman. Rute aman, dan kesalahan dalam sistem peringatan telah teratasi.",
  ui_story_30020601_82_dialog_content = "Misi selesai, aku kembali ke markas.",
  ui_story_30020601_83_dialog_content = "Aneh...",
  ui_story_30020601_84_dialog_content = "Hanya ada aku di titik pertemuan...",
  ui_story_30020601_85_dialog_content = "Hanya ada dua titik periksa di rute yang mereka pilih. Dalam keadaan normal, mereka seharusnya kembali sebelum aku tiba.",
  ui_story_30020601_86_dialog_content = "Apa jangan-jangan mereka menghadapi Eclipsite...?",
  ui_story_30020601_87_dialog_content = "Ada yang tidak beres. Aku harus memeriksa mereka!",
  ui_story_30020601_88_dialog_content = "Sialan! Mengapa ada begitu banyak Eclipsites?!",
  ui_story_30020601_89_dialog_content = "Aduh! Saya terluka...",
  ui_story_30020601_90_dialog_content = "Sebelah sini! Masih ada satu lagi!",
  ui_story_30020601_91_dialog_content = "Mereka terus berdatangan... Pertahankan barisan, teman-teman!",
  ui_story_30020601_92_dialog_content = "Para Eclipsite... Mereka mengincar kalian di sana! Awas!",
  ui_story_30020601_93_dialog_content = "Bajingan... Beraninya kau...",
  ui_story_30020601_94_dialog_content = "Sial... Perbanku copot... Pendarahanku tidak bisa berhenti...",
  ui_story_30020601_95_dialog_content = "Tapi, meski begitu...",
  ui_story_30020601_96_dialog_content = "Apa pun yang terjadi... Aku takkan mati di tempat seperti ini... Tidak akan!",
  ui_story_30020601_97_dialog_content = "Jayalah Illumina! Matilah kalian!!!",
  ui_story_30020601_98_dialog_content = "Sudah kuduga ada yang tidak beres!",
  ui_story_30020601_99_dialog_content = "Tetap tenang! Bantu aku menyerang sayap kanan! Kita perlu membuat celah!",
  ui_story_30020601_100_dialog_content = "Apa itu... Hiiro? Benar! Itu Hiiro!",
  ui_story_30020601_101_dialog_content = "Bantu kami!!!",
  ui_story_30020601_102_dialog_content = "Graaagh!",
  ui_story_30020601_103_dialog_content = "Mereka datang!",
  ui_story_30020601_104_dialog_content = "Anda mengambil yang terdekat! Serahkan sisanya padaku!",
  ui_story_30020601_105_dialog_content = "Dan begitu saja, kami membalikkan keadaan.",
  ui_story_30020601_106_dialog_content = "Apa itu...?",
  ui_story_30020601_107_dialog_content = "Hei! Awasi bagian samping!",
  ui_story_30020601_108_dialog_content = "Aku tahu!",
  ui_story_30020601_109_dialog_content = "Sudah hampir mati, tapi masih mau menyelinap ke arahku, ya?!",
  ui_story_30020601_110_dialog_content = "Fiuh... Akhirnya selesai juga...",
  ui_story_30020601_111_dialog_content = "Kami berutang nyawa padamu, Hiiro!",
  ui_story_30020601_112_dialog_content = "Syukurlah kamu datang...",
  ui_story_30020601_113_dialog_content = "Kamu... Kamu baru saja menyelamatkanku, 'kan?",
  ui_story_30020601_114_dialog_content = "Jangan biarkan itu masuk ke kepalamu... Aku masih bisa mengukir jalan keluar dari sini tanpamu!",
  ui_story_30020601_115_dialog_content = "Bagus... Kelihatannya kamu masih bisa bergerak.",
  ui_story_30020601_116_dialog_content = "Hiiro... Sepeda motormu...",
  ui_story_30020601_117_dialog_content = "Saya pikir Anda merusaknya ketika Anda baru saja mengisi daya ...",
  ui_story_30020601_118_dialog_content = "Aku tahu. Tidak apa-apa.",
  ui_story_30020601_119_dialog_content = "Kamu masih bisa berjalan?",
  ui_story_30020601_120_dialog_content = "Ya!",
  ui_story_30020601_121_dialog_content = "Bagus. Siapa pun yang masih bisa berjalan, bantu bawa yang terluka kembali ke pangkalan.",
  ui_story_30020601_122_dialog_content = "Hai! Aku berbicara padamu, Hiiro! Paling tidak yang bisa Anda lakukan adalah melihat saya!",
  ui_story_30020601_123_dialog_content = "Aku tak pernah memintamu menyelamatkanku, dengar? Aku bisa melakukannya sendiri!",
  ui_story_30020601_124_dialog_content = "Kamu menyelesaikan misi tim kita sendirian... Kamu juga menyelamatkan semua orang...",
  ui_story_30020601_125_dialog_content = "Bukankah itu sudah cukup untuk kembali dan melapor kepada atasan?",
  ui_story_30020601_126_dialog_content = "Kenapa kamu menyelamatkanku juga?!",
  ui_story_30020601_127_dialog_content = "Bukan karena alasan apa pun.",
  ui_story_30020601_128_dialog_content = "Kita semua akan mati suatu hari nanti, tapi hari ini bukan hari itu untukmu.",
  ui_story_30020601_129_dialog_content = "Kau...!",
  ui_story_30020601_130_dialog_content = "<color=#e8d9bb>Tak lama setelahnya…</color>",
  ui_story_30020601_131_dialog_content = "Jenderal Agung Hiiro, Komandan Legiun ke-3 Federasi Illumina!",
  ui_story_30020601_132_dialog_content = "Bagaimana saya harus merujuk Anda sekarang? Saya kira biasa Hiiro yang Agung masih akan berfungsi, atau Anda punya saran yang lebih baik?",
  ui_story_30020601_133_dialog_content = "Utarakan pikiranmu.",
  ui_story_30020601_134_dialog_content = "Kamu sadar seseorang melaporkanmu tepat sebelum pengangkatanmu?",
  ui_story_30020601_135_dialog_content = "Mereka mengatakan bahwa Anda tidak mengerti bagaimana bekerja sebagai tim, bahwa Anda datang dan pergi sesuka Anda... bahwa Anda dingin dan menyendiri...",
  ui_story_30020601_136_dialog_content = "Mereka tidak salah, sejauh yang saya bisa lihat.",
  ui_story_30020601_137_dialog_content = "Jadi?",
  ui_story_30020601_138_dialog_content = "\"Jadi\"? Itu saja yang ingin kamu katakan?!",
  ui_story_30020601_139_dialog_content = "Tsk... Aku tahu kamu dan Grand Marshal sudah dekat.",
  ui_story_30020601_140_dialog_content = "Begitu dekat, sampai-sampai kamu tak ambil pusing jika <color=#FFB400>difitnah</color>. Iya, 'kan?",
  ui_story_30020601_141_dialog_content = "Anda menganggap ini fitnah?",
  ui_story_30020601_142_dialog_content = "Yah... Jelas beberapa di antaranya benar!",
  ui_story_30020601_143_dialog_content = "Namun meski begitu, saya mengajukan bukti untuk membantah klaim palsu mereka.",
  ui_story_30020601_144_dialog_content = "Banyak orang maju untuk bersaksi membela Anda juga.",
  ui_story_30020601_145_dialog_content = "Dan... aku berhasil memperbaiki motormu yang rusak.",
  ui_story_30020601_146_dialog_content = "Untuk mengumpulkan bukti, tentu saja!",
  ui_story_30020601_147_dialog_content = "Hmm.",
  ui_story_30020601_148_dialog_content = "\"Hmm\"...?! Jawaban macam apa itu?!",
  ui_story_30020601_149_dialog_content = "Kamu hanya bisa bilang begitu kepada seseorang yang baru saja menyelamatkan seluruh kariermu?!",
  ui_story_30020601_150_dialog_content = "Atau apa kamu mencoba mengatakan bahwa kamu tidak peduli jika aku membantumu atau tidak?!",
  ui_story_30020601_151_dialog_content = "Hmm.",
  ui_story_30020601_152_dialog_content = "K-kau...!!!",
  ui_story_30020601_153_dialog_content = "Terima kasih telah mengajukan bukti demi aku.",
  ui_story_30020601_154_dialog_content = "Meski tuduhan itu ada benarnya...",
  ui_story_30020601_155_dialog_content = "A-aku tidak melakukannya untukmu... Aku melakukannya karena aku orang baik!",
  ui_story_30020601_156_dialog_content = "Saya tidak pernah tahu Anda memiliki sejarah yang menarik, Hiiro...",
  ui_story_30020601_157_dialog_content = "\"Seru\"?",
  ui_story_30020601_158_dialog_content = "Ya! Aku tidak tahu kau tahu cara mengendarai sepeda motor...",
  ui_story_30020601_159_dialog_content = "Kalau dipikir-pikir, aku belum pernah melihatmu mengendarainya... atau memakai seragam itu di foto ini.",
  ui_story_30020601_160_dialog_content = "Saya tidak punya alasan untuk memakainya lagi setelah lulus dari akademi. Sepertinya mereka memiliki desain baru untuk seragam siswa sekarang.",
  ui_story_30020601_161_dialog_content = "Sementara untuk sepeda motornya, kuserahkan kembali kepada tim patroli setelah diperbaiki. Mungkin masih bermanfaat.",
  ui_story_30020601_162_dialog_content = "Aku mengerti... dan teman sekelasmu...",
  ui_story_30020601_163_dialog_content = "Meskipun sikapnya tidak baik, kelihatannya dia seperti orang yang mengerti banyak hal.",
  ui_story_30020601_164_dialog_content = "Dimana dia sekarang? Apakah dia bergabung dengan Legiun ke-3 setelah lulus, sama sepertimu?",
  ui_story_30020601_165_dialog_content = "... Entahlah.",
  ui_story_30020601_166_dialog_content = "K-kamu tidak tahu...?",
  ui_story_30020601_167_dialog_content = "Kami tidak pernah saling bertemu lagi setelah insiden itu.",
  ui_story_30020601_168_dialog_content = "Saya juga belum pernah mendengar apa pun tentang pekerjaan atau kariernya.",
  ui_story_30020601_169_dialog_content = "Yah, memang tidak ada alasan untuk mencari tahu.",
  ui_story_30020601_170_dialog_content = "Jika pendapat dan posisi setiap orang berubah seiring waktu, tetapi mereka masih mengkhawatirkan diri dengan apa yang disebut persahabatan semu masa lalu...",
  ui_story_30020601_171_dialog_content = "Itu hanya akan membuat masalah saat ini begitu rumit.",
  ui_story_30020601_172_dialog_content = "Menghabiskan beberapa masa muda kita bersama sudah merupakan hal yang baik. Cukup baik.",
  ui_story_30020601_173_dialog_content = "(Meskipun Hiiro terdengar tenang dan acuh tak acuh...)",
  ui_story_30020601_174_dialog_content = "(Dia hampir tidak pernah berbicara panjang lebar...)",
  ui_story_30020601_175_dialog_content = "(Mungkinkah... bahwa dia juga merasa sedikit bernostalgia tentang hari-hari itu?)",
  ui_story_30020601_176_dialog_content = "(Kalau tidak, dia tidak akan keluar seperti itu dari melihat gambar, kan...?)",
  ui_story_30020601_177_dialog_content = "(Saya rasa saya tahu apa yang harus dilakukan...)",
  ui_story_30020601_178_dialog_content = "May Saya melihat gambar itu lagi?",
  ui_story_30020601_179_dialog_content = "Tentu.",
  ui_story_30020601_180_dialog_content = "(Topi militer, jubah hitam, beberapa lencana, dan sepasang sepatu bot tentara. Semuanya dengan bekas keausan dari pertempuran yang tak terhitung jumlahnya di masa lalu...)",
  ui_story_30020601_181_dialog_content = "Apakah ada sesuatu di pikiran Anda? Anda menatap foto itu dengan sangat saksama...",
  ui_story_30020601_182_dialog_content = "T-tidak, tidak ada apa-apa! Aku hanya berpikir kamu terlihat sangat mengesankan dengan seragam itu...",
  ui_story_30020601_183_dialog_content = "Anda sudah mengatakan itu.",
  ui_story_30020601_184_dialog_content = "Jika tidak ada yang lain, aku pergi sekarang.",
  ui_story_30020601_185_dialog_content = "Sampai jumpa.",
  ui_story_30020601_186_dialog_content = "<color=#e8d9bb>Sepuluh hari kemudian</color>",
  ui_story_30020601_187_dialog_content = "Akhirnya selesai...",
  ui_story_30020601_188_dialog_content = "Ini jauh lebih sulit dari yang kubayangkan...",
  ui_story_30020601_189_dialog_content = "Benar... Ayo lakukan! Aku tinggal memberikannya kepadanya!",
  ui_story_30020601_190_dialog_content = "<color=#e8d9bb>Tok Tok Tok...</color>",
  ui_story_30020601_191_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_30020601_192_dialog_content = "Hmm? Apakah Hiiro tidak ada di kamarnya?",
  ui_story_30020601_193_dialog_content = "Dia pasti memiliki urusan militer yang penting untuk diurus... Aku benar-benar berharap untuk memberikan ini padanya secara pribadi...",
  ui_story_30020601_194_dialog_content = "Kurasa aku harus meninggalkannya di depan pintu rumahnya dan mencatatnya. \"Hadiah untuk...\"",
  ui_story_30020601_195_dialog_content = "\"... Hiiro.\"",
  ui_story_30020601_196_dialog_content = "Ini sudah ke 34 kalinya saya salah potong kain hari ini...",
  ui_story_30020601_197_dialog_content = "Lalu, bahan untuk sepatu botnya... Aku juga mengacaukannya...",
  ui_story_30020601_198_dialog_content = "Aaargh!!",
  ui_story_30020601_199_dialog_content = "Memberikan seragam yang sama dengan yang ada di foto kepada Hiiro sepertinya ide yang sederhana...",
  ui_story_30020601_200_dialog_content = "Kenapa sulit sekali dilakukan, sih?!",
  ui_story_30020601_201_dialog_content = "Apa ada cara yang lebih baik untuk melakukannya, ya?",
  ui_story_30020601_202_dialog_content = "<color=#e8d9bb>Cloudrover Guild</color>",
  ui_story_30020601_203_dialog_content = "Seorang pelanggan yang terhormat telah tiba...",
  ui_story_30020601_204_dialog_content = "May Saya bertanya apa yang Anda cari hari ini?",
  ui_story_30020601_205_dialog_content = "Halo, Nona Sheol. Saya ingin tahu... apakah Anda memiliki stok pakaian ini?",
  ui_story_30020601_206_dialog_content = "Oh? Seragam pelatihan Illumina Military Academy gaya lama...",
  ui_story_30020601_207_dialog_content = "Tepat sekali! Apakah di sini tersedia?",
  ui_story_30020601_208_dialog_content = "Kemampuan Cloudrover Guild untuk memenuhi kebutuhan pelanggan sepenuhnya bergantung pada harga yang bersedia mereka bayarkan...",
  ui_story_30020601_209_dialog_content = "A-Apakah... 10.000 Nightium... cukup...?",
  ui_story_30020601_210_dialog_content = "Oh?",
  ui_story_30020601_211_dialog_content = "Hanya itu yang kumiliki!",
  ui_story_30020601_212_dialog_content = "Kamu memang pelanggan yang murah hati... Ya, bisa dibilang jumlah ini lebih dari mencukupi.",
  ui_story_30020601_213_dialog_content = "I-Begitukah... <size=30>Saya akan menawarkan lebih sedikit jika saya mengetahuinya ...</size>",
  ui_story_30020601_214_dialog_content = "Aku ingin tahu apakah Hiiro...",
  ui_story_30020601_215_dialog_content = "Akan menyukai hadiah ini?",
  ui_story_30020601_216_dialog_content = "<color=#e8d9bb>Tiga hari kemudian, di suatu tempat di dekat garis pertahanan Illumina...</color>",
  ui_story_30020601_217_dialog_content = "Laporanku sudah selesai, Navigator! Terima kasih telah ikut!",
  ui_story_30020601_218_dialog_content = "Oh, ya, kudengar Commander Hiiro seharusnya ada di sekitar sini hari ini!",
  ui_story_30020601_219_dialog_content = "Hihi... Semua orang bilang tingkahnya sangat bertolak belakang akhir-akhir ini...",
  ui_story_30020601_220_dialog_content = "Ingin pergi melihat apa yang legendaris Panglima Hiiro terserah?",
  ui_story_30020601_221_dialog_content = "Saya yakin dia tidak akan meminta pertanggungjawaban saya atas apa pun jika Anda ada di sana bersama saya!",
  ui_story_30020601_222_dialog_content = "Komandan legendaris Hiiro... Apakah itu yang mereka sebut dia sekarang...?",
  ui_story_30020601_223_dialog_content = "Tentu, ayo kita sapa.",
  ui_story_30020601_224_dialog_content = "(Aku belum mendengar kabarnya selama beberapa hari terakhir ini. Ini akan memberiku kesempatan untuk bertanya apakah dia sudah dapat hadiahku juga...)",
  ui_story_30020601_225_dialog_content = "Hiiro...!",
  ui_story_30020601_226_dialog_content = "Oh, ternyata kau.",
  ui_story_30020601_227_dialog_content = "Pakaianmu...",
  ui_story_30020601_228_dialog_content = "Hmm. Betul sekali.",
  ui_story_30020601_229_option_content = "Aku takut bahwa Anda tidak mendapatkannya.",
  ui_story_30020601_230_dialog_content = "Maaf. Karena sangat sibuk belakangan ini, sampai-sampai aku lupa mengirimkan ucapan terima kasihku.",
  ui_story_30020601_231_dialog_content = "Ah, t-tidak apa-apa, kok! Lagi pula, kamu seorang Commander...",
  ui_story_30020601_232_option_content = "Pakaiannya sangat cocok untukmu!",
  ui_story_30020601_233_dialog_content = "Kupikir seragam itu sangat cocok untukmu, Hiiro!",
  ui_story_30020601_234_dialog_content = "Terima kasih, PlayerName.",
  ui_story_30020601_235_dialog_content = "S-sama-sama...",
  ui_story_30020601_236_dialog_content = "Tapi, sungguh, seragamnya sangat cocok untukmu, Hiiro!",
  ui_story_30020601_237_dialog_content = "Aku tidak terbiasa mengucapkan terima kasih dua kali...",
  ui_story_30020601_238_dialog_content = "Namun, aku harus mengungkapkan rasa terima kasihku sekali lagi padamu karena...",
  ui_story_30020601_239_dialog_content = "Selain hadiahmu, kamu juga membantuku menyadari sesuatu...",
  ui_story_30020601_240_dialog_content = "...Bahwa aku harus lebih memperhatikan rekan-rekanku dan lebih sering memeriksa mereka.",
  ui_story_30020601_241_dialog_content = "Setelah Anda memberi saya seragam ini, saya bertanya kepada seseorang tentang teman sekelas saya untuk melihat bagaimana keadaannya.",
  ui_story_30020601_242_dialog_content = "Saya pikir seseorang yang ambisius seperti dia akan tetap di militer dan naik pangkat ...",
  ui_story_30020601_243_dialog_content = "Tapi yang mengejutkan saya, dia beralih ke logistik dan menjadi pengangkut, memindahkan barang antar kota.",
  ui_story_30020601_244_dialog_content = "Seorang pengangkut?",
  ui_story_30020601_245_dialog_content = "Ya. Secara khusus, mereka yang mengoperasikan Kaas, kendaraan kargo Illumina yang terkenal.",
  ui_story_30020601_246_dialog_content = "Kudengar dia pengemudi yang hebat.",
  ui_story_30020601_247_dialog_content = "Kamu menjadi Legion Commander, sementara teman sekelasmu menjadi pengemudi pengantar?",
  ui_story_30020601_248_dialog_content = "Kenapa aku merasa seperti, dengan kepribadian seperti itu...",
  ui_story_30020601_249_dialog_content = "Kamu salah.",
  ui_story_30020601_250_dialog_content = "Dia sangat puas dengan pekerjaan dan statusnya.",
  ui_story_30020601_251_dialog_content = "\"Saya tidak peduli apa yang saya lakukan atau di mana saya melakukannya, selama itu melayani Illumina.\" Itu adalah kata-kata teman sekelas saya.",
  ui_story_30020601_252_dialog_content = "Dia bilang, dia juga terkenang akan hari-hari itu...",
  ui_story_30020601_253_dialog_content = "Tentu saja, \"penyelamatan tanpa pamrih\" dari Komandan Legiun ke-3 masih menjadi kenangan terindahnya...",
  ui_story_30020601_254_dialog_content = "Memang begitulah dia.",
  ui_story_30020601_255_dialog_content = "Pengakuan jujurnya membuatku tersadar bahwa aku juga merindukan waktu kami bersama di akademi.",
  ui_story_30020601_256_dialog_content = "Kami berdua mengenakan seragam ini, dan bertarung di sisi satu sama lain.",
  ui_story_30020601_257_dialog_content = "Meskipun memiliki perbedaan, kami saling membantu dan melindungi.",
  ui_story_30020601_258_dialog_content = "Mungkin kini kami tidak bekerja di tempat yang sama, tetapi tanpa disadari, kami selalu bekerja demi tujuan yang sama.",
  ui_story_30020601_259_dialog_content = "Sebenarnya, kami adalah tim.",
  ui_story_30020601_260_dialog_content = "Selama Anda berdua bekerja menuju tujuan yang sama, Anda berdua akan selalu berada di tim yang sama.",
  ui_story_30020601_261_dialog_content = "Maaf?",
  ui_story_30020601_262_dialog_content = "B-bukan seperti itu! Aku, eh... Lupakan.",
  ui_story_30020601_263_dialog_content = "Apa pun itu, kamu benar.",
  ui_story_30020601_264_dialog_content = "Seperti...",
  ui_story_30020601_265_dialog_content = "Bagaimana kita pernah bertarung bersama, 'kan?",
  ui_story_30020601_266_dialog_content = "Saya tidak akan pernah melupakan serangan yang menghalau Tabaad.",
  ui_story_30020601_267_dialog_content = "Mendengarnya saja sudah lebih dari cukup.",
  ui_story_30020601_268_dialog_content = "Perjalanan yang telah kita tempuh cukup jauh, 'kan?",
  ui_story_30020601_269_dialog_content = "Omong-omong, namanya Lucy. Kurasa aku harus memberitahumu.",
  ui_story_30020601_270_dialog_content = "Lucy... Prajurit biasa Illumina.",
  ui_story_30020602_1_dialog_content = "\"Halo.\"",
  ui_story_30020602_2_dialog_content = "\"Angin menjadi kering dan dingin dengan perubahan musim. Saya berdoa untuk kesejahteraanmu, serta kesejahteraan teman-temanmu.\"",
  ui_story_30020602_3_dialog_content = "\"Cloud Mountain telah tenang setelah kepergian Anda. Tidak ada Eclipsite yang muncul di dalam penghalang sejak itu.\"",
  ui_story_30020602_4_dialog_content = "\"Namun, kami melihat pergerakan yang tidak biasa pada segel yang menjaga penghalang tetap di tempat.\"",
  ui_story_30020602_5_dialog_content = "\"Gerakan abnormal itu berhenti secepat saat dimulai, dan tidak memiliki efek yang terlihat pada penghalang.\"",
  ui_story_30020602_6_dialog_content = "\"Untuk alasan ini, saya ragu untuk memberi tahu Anda tentang ini. Namun, Sanki bersikeras meminta Anda untuk kembali dan melakukan penyelidikan yang tepat—\"",
  ui_story_30020602_7_dialog_content = "Hah? Itu Sanki? Sepertinya dia telah tumbuh jauh lebih dewasa sekarang.",
  ui_story_30020602_8_dialog_content = "Cahaya bulan yang dipantulkan oleh bilah pedang, bersinar dingin dan jernih.",
  ui_story_30020602_9_dialog_content = "Keinginan Sanki untuk melindungi Cloud Mountain tidak berbeda. Meskipun dia bisa terlalu mendominasi kadang-kadang, hati dan niatnya murni.",
  ui_story_30020602_10_dialog_content = "Aku tidak akan mengecewakannya.",
  ui_story_30020602_11_dialog_content = "... Jadi apakah itu berarti kamu akan pergi ke Cloud Mountain untuk menyelidiki penghalang tersebut?",
  ui_story_30020602_12_dialog_content = "Ya.",
  ui_story_30020602_13_dialog_content = "B-Disini dan sekarang?",
  ui_story_30020602_14_dialog_content = "Benar.",
  ui_story_30020602_15_dialog_content = "Bahkan setelah Grand Marshal meninggalkanmu dengan lima tumpukan pekerjaan akhir tahun untuk dikerjakan?!",
  ui_story_30020602_16_dialog_content = "Aku sudah menyelesaikan pekerjaan-pekerjaan itu.",
  ui_story_30020602_17_dialog_content = "<size=45>Semua itu?!?</size>",
  ui_story_30020602_18_dialog_content = "Apa kamu, mesin? Kebanyakan orang harus bekerja malam hari selama sebulan hanya untuk menyelesaikan semua itu. Tubuh siapa pun tidak bisa menangani stres seperti itu!",
  ui_story_30020602_19_dialog_content = "Surat dari Granny telah memberikan banyak hal untuk aku khawatirkan. Tanpa sadar, aku telah menyelesaikan semua pekerjaanku.",
  ui_story_30020602_20_dialog_content = "Saya tidak berpikir itu adalah sesuatu yang bisa kamu lakukan \"tanpa menyadarinya\"...",
  ui_story_30020602_21_dialog_content = "PlayerName... Apakah kamu juga sibuk belakangan ini?",
  ui_story_30020602_22_dialog_content = "Tidak benar-benar, tidak. Tidak ada pekerjaan saya yang mendesak sekarang... Kenapa?",
  ui_story_30020602_23_dialog_content = "Oh, aku tahu kenapa! Kamu ingin aku mengantarmu ke Cloud Island, kan? Tidak masalah; serahkan saja padaku!",
  ui_story_30020602_24_dialog_content = "...",
  ui_story_30020602_25_dialog_content = "Uh, apakah aku salah?",
  ui_story_30020602_26_dialog_content = "... Tidak, tebakanmu benar.",
  ui_story_30020602_27_dialog_content = "Aku hanya tidak terbiasa dengan perasaan ini... seseorang tahu apa yang aku inginkan sebelum aku bahkan bertanya.",
  ui_story_30020602_28_dialog_content = "Rasanya seperti aku sedang memanfaatkanmu.",
  ui_story_30020602_29_dialog_content = "Hahaha, sama sekali tidak! Kau selalu merawatku, jadi ini adalah hal terkecil yang bisa kulakukan untukmu!",
  ui_story_30020602_30_dialog_content = "Kamu punya ucapan terima kasihku. Sejujurnya, aku tidak akan bisa berbuat banyak tanpa bantuanmu.",
  ui_story_30020602_31_dialog_content = "Aku tidak bisa masuk ke penghalang Cloud Mountain. Untuk menghindari kesalahan, aku butuh bantuan seseorang yang bisa merasakan batas penghalang tersebut.",
  ui_story_30020602_32_dialog_content = "Dan mengingat kecepatan dan efektivitas, tidak ada yang lebih baik untuk tugas ini daripada kamu.",
  ui_story_30020602_33_dialog_content = "PlayerName, maukah kamu ikut dengan saya dan memberikan dukunganmu?",
  ui_story_30020602_34_dialog_content = "(Dia meminta bantuan saya dengan sopan setelah semua ini. Saya rasa Hiiro adalah kesopanan yang tidak akan pernah hilang...)",
  ui_story_30020602_35_dialog_content = "Serahkan saja padaku! Caelestite selalu menyelesaikan tugasnya!",
  ui_story_30020602_36_dialog_content = "...",
  ui_story_30020602_37_dialog_content = "Ahem... Maaf tentang itu. Akhir-akhir ini saya sedang mengerjakan slogan baru, dan saya meneriakkannya setiap kali saya mendapatkan pekerjaan baru.",
  ui_story_30020602_38_dialog_content = "Ini tidak akan terjadi lagi, aku janji.",
  ui_story_30020602_39_dialog_content = "Ahh, Cloud Island selalu damai dan tenang seperti biasanya.",
  ui_story_30020602_40_dialog_content = "Saya minta maaf atas penundaan ini, PlayerName.",
  ui_story_30020602_41_dialog_content = "Wow! K-Kamu terlihat luar biasa dengan gaun ini...",
  ui_story_30020602_42_dialog_content = "... Ini adalah pakaian tradisional dari Keluarga Sakura. Granny memberikannya kepada saya sebelum kita berangkat kali terakhir.",
  ui_story_30020602_43_dialog_content = "Selama bertahun-tahun, dia telah bekerja tanpa lelah untuk melindungi penghalang.",
  ui_story_30020602_44_dialog_content = "Sebagai keturunan dari Keluarga Sakura, saya merasa bahwa saya harus menawarkan rasa terima kasih saya yang tulus, itulah sebabnya saya mengganti pakaian ini.",
  ui_story_30020602_45_dialog_content = "Meski sepertinya itu tidak cocok denganku—",
  ui_story_30020602_46_dialog_content = "Pas sekali denganmu!",
  ui_story_30020602_47_dialog_content = "Karakter heroik dan rambut merah muda yang cerah adalah pasangan yang sempurna untuk pakaian cantik ini!",
  ui_story_30020602_48_dialog_content = "Faktanya, dengan cara mereka menonjolkan kepribadianmu yang elegan dan berwibawa, saya akan bilang mereka diciptakan hanya untukmu!",
  ui_story_30020602_49_dialog_content = "Aku tidak benar-benar tahu bagaimana mengungkapkannya dengan kata-kata... Tapi aku tetap terpesona!",
  ui_story_30020602_50_dialog_content = "PlayerName…",
  ui_story_30020602_51_dialog_content = "Heheh, untuk seseorang yang tidak tahu apa yang harus dikatakan, kamu cukup pandai berkata-kata, pemuda.",
  ui_story_30020602_52_dialog_content = "G-Granny?! Kamu seharusnya mengatakan sesuatu saat kamu tiba di sini!",
  ui_story_30020602_53_dialog_content = "Aku berniat menyambutmu, tapi...",
  ui_story_30020602_54_dialog_content = "Ketika aku melihat kalian berdua berdiri di sana, aku tidak tega untuk mengganggu.",
  ui_story_30020602_55_dialog_content = "Granny...!",
  ui_story_30020602_56_dialog_content = "Selain menyelidiki penghalang, saya juga ingin mengunjungi Anda.",
  ui_story_30020602_57_dialog_content = "Jadi tolong jangan menganggap dirimu sebagai gangguan dalam bentuk apa pun.",
  ui_story_30020602_58_dialog_content = "Heheh, baik untuk bersikap sopan dan tenang, Hiiro, tapi kau tidak seharusnya terlalu tegang sepanjang waktu.",
  ui_story_30020602_59_dialog_content = "Setelah semua, kamu terlihat sangat menggemaskan saat berbicara dengan PlayerName barusan.",
  ui_story_30020602_60_dialog_content = "...",
  ui_story_30020602_61_dialog_content = "(Uh-oh, Hiiro tidak baik dalam situasi seperti ini...)",
  ui_story_30020602_62_dialog_content = "Senang bertemu denganmu lagi, PlayerName. Kau tampak lebih tinggi, bukan?",
  ui_story_30020602_63_dialog_content = "Oh my, sepertinya kamu juga telah menjadi lebih tampan!",
  ui_story_30020602_64_dialog_content = "Sangat baik, sangat baik. Itu memenuhi hati saya dengan kebahagiaan melihat kalian berdua.",
  ui_story_30020602_65_dialog_content = "Oh, Granny, kamu membuatku malu... Hahaha...",
  ui_story_30020602_66_dialog_content = "Aku mengawasimu berdua dari kejauhan, dan kalian sangat mengingatkan saya pada orang tua Hiiro beberapa tahun lalu.",
  ui_story_30020602_67_dialog_content = "Waktu mencuri begitu banyak dari kita, tetapi juga membawa kita hal-hal baru dan indah, seperti pasangan muda...",
  ui_story_30020602_68_dialog_content = "\"Pasangan muda\"? K-Kamu pasti salah paham di sini, Granny...",
  ui_story_30020602_69_dialog_content = "(Aku benar-benar bingung. Apa yang sedang terjadi di sini? Kenapa rasanya seperti aku baru pertama kali bertemu dengan keluarga seseorang?!)",
  ui_story_30020602_70_dialog_content = "K-Katakan, Granny, saya tidak melihat Sanki di sekitar...?",
  ui_story_30020602_71_dialog_content = "Oh, jangan terlalu berharap. Dia tidak ingin Hiiro melihatnya sampai dia siap untuk mengesankan dia.",
  ui_story_30020602_72_dialog_content = "Saya senang dia termotivasi.",
  ui_story_30020602_73_dialog_content = "(Oh bagus, dia sudah mendapatkan kembali ketenangannya!)",
  ui_story_30020602_74_dialog_content = "Ceritakan tentang penghalang itu, Granny. Apakah kamu sudah berkonsultasi dengan pendeta di pulau utama tentang itu?",
  ui_story_30020602_75_dialog_content = "Ya, saya pernah. Awalnya saya pikir bahwa gerakan itu terhubung dengan pulau utama, tetapi pendeta mengklaim bahwa mereka berasal dari tempat yang jauh lebih jauh.",
  ui_story_30020602_76_dialog_content = "Sangat mungkin bahwa suku dewa gunung sedang memanggil dari timur.",
  ui_story_30020602_77_dialog_content = "... Suku dewa gunung?",
  ui_story_30020602_78_dialog_content = "Jadi gerakan-gerakan itu adalah respon dewa gunung kepada penduduknya? Sungguh misterius...",
  ui_story_30020602_79_dialog_content = "Dan penghalang tetap tidak terpengaruh?",
  ui_story_30020602_80_dialog_content = "Sepertinya begitu, setidaknya untuk saat ini. Itulah sebabnya saya tidak ingin mengganggu pekerjaanmu...",
  ui_story_30020602_81_dialog_content = "Seperti yang saya katakan, jangan anggap dirimu sebagai beban. Cloud Island juga adalah rumahku.",
  ui_story_30020602_82_dialog_content = "Meskipun hanya sebagai langkah pencegahan, saya ingin menyelidiki daerah ini secara menyeluruh.",
  ui_story_30020602_83_dialog_content = "Saya senang mendengarnya, Hiiro. Terima kasih telah datang jauh-jauh demi kami.",
  ui_story_30020602_84_dialog_content = "Berkat PlayerName, itu sama sekali tidak merepotkan.",
  ui_story_30020602_85_dialog_content = "Jika ada yang harus kita syukuri, seharusnya kita semua berterima kasih kepada kamu yang telah mempertahankan barier selama bertahun-tahun...",
  ui_story_30020602_86_dialog_content = "Atas nama Keluarga Sakura dan Sakae, saya ingin menyampaikan rasa terima kasih dan hormat kami yang sebesar-besarnya.",
  ui_story_30020602_87_dialog_content = "Oh, tidak perlu itu. Saya melakukan ini karena saya ingin melakukannya. Itu seperti yang kamu katakan...",
  ui_story_30020602_88_dialog_content = "\"Cloud Island juga adalah rumahku.\"",
  ui_story_30020602_89_dialog_content = "<anim type=Shake>Grahhh!</anim>",
  ui_story_30020602_90_dialog_content = "<color=#e8d9bb>Plak! Tabok, tabok!</color>",
  ui_story_30020602_91_dialog_content = "Graah—",
  ui_story_30020602_92_dialog_content = "Itu seharusnya yang terakhir dari mereka.",
  ui_story_30020602_93_dialog_content = "Syukurlah...!",
  ui_story_30020602_94_dialog_content = "Tampaknya barier di setiap lokasi bertahan dengan baik.",
  ui_story_30020602_95_dialog_content = "Beberapa Eclipsite yang berkeliaran di sini juga tidak berani melewatinya. Saya rasa gerakan segel tidak mempengaruhi kekuatan penghalang.",
  ui_story_30020602_96_dialog_content = "Itu melegakan, bukan?",
  ui_story_30020602_97_dialog_content = "Ya. Kita bisa pergi dengan tahu bahwa Cloud Island sangat aman untuk saat ini.",
  ui_story_30020602_98_dialog_content = "...",
  ui_story_30020602_99_dialog_content = "(Hiiro sedang menatap pegunungan... Apakah dia merasa rindu rumah?)",
  ui_story_30020602_100_dialog_content = "Mengapa kita tidak melihat-lihat Gunung Awan di pulau terdekat? Saya ingat pemandangan gunung itu sangat indah saat dilihat dari kejauhan.",
  ui_story_30020602_101_dialog_content = "…!",
  ui_story_30020602_102_dialog_content = "Kemampuanmu untuk berempati dengan orang lain hampir saja menakutkan.",
  ui_story_30020602_103_dialog_content = "Anda tidak menggunakan kekuatan Anda pada saya barusan, kan?",
  ui_story_30020602_104_dialog_content = "Tidak! Tak akan!",
  ui_story_30020602_105_dialog_content = "... Aku hanya ingin melihatmu bahagia, itu saja. Menggunakan kekuatanku hanya akan memberikan efek yang berlawanan.",
  ui_story_30020602_106_dialog_content = "Tenang. Aku hanya bercanda.",
  ui_story_30020602_107_dialog_content = "Oh... Itu hanya bercandaan... Hahaha...",
  ui_story_30020602_108_dialog_content = "Eh, sebentar...",
  ui_story_30020602_109_dialog_content = "<size=45>Kamu lah yang menakutkan, Hiiro!</size>",
  ui_story_30020602_110_dialog_content = "Wow, cuaca hari ini membuat Cloud Mountain terlihat semakin memukau!",
  ui_story_30020602_111_dialog_content = ".... Ya.",
  ui_story_30020602_112_dialog_content = "Jadi itulah tempat dewa gunung tidur, ya? Aku berharap suku timur bisa bertemu dengannya suatu hari nanti.",
  ui_story_30020602_113_dialog_content = "Hmm.",
  ui_story_30020602_114_dialog_content = "Sanki sangat fokus mengejarmu. Saya bertanya-tanya apakah dia telah membantu Granny mengumpulkan kayu bakar...",
  ui_story_30020602_115_dialog_content = "Hmm.",
  ui_story_30020602_116_dialog_content = "... Apa masalahnya, Hiiro? Kamu terdiam sepanjang waktu ini.",
  ui_story_30020602_117_dialog_content = "...",
  ui_story_30020602_118_dialog_content = "Meskipun rumahku tepat di depanku, tetap saja terasa begitu jauh. Saya tidak bisa tidak merasa agak kesepian.",
  ui_story_30020602_119_dialog_content = "Tapi saat aku melihatnya bersamamu, kesepian itu terasa hangat.",
  ui_story_30020602_120_dialog_content = "Saya tidak bisa membayangkan betapa dinginnya duduk di sini sendirian.",
  ui_story_30020602_121_dialog_content = "Kamu tidak perlu khawatir tentang itu juga. Hari itu tidak akan pernah datang.",
  ui_story_30020602_122_dialog_content = "Karena aku akan selalu ada untuk membawamu kembali ke Cloud Island dengan Colossus-ku!",
  ui_story_30020602_123_dialog_content = "Caelestite selalu mendapatkan—Eh, tidak apa-apa.",
  ui_story_30020602_124_dialog_content = "...",
  ui_story_30020602_125_dialog_content = "Heheh.",
  ui_story_30020602_126_dialog_content = "Kamu baru saja tersenyum...",
  ui_story_30020602_127_dialog_content = "(Hah? Ada sesuatu di dekat sini...)",
  ui_story_30020602_128_option_content = "Psychic Scan",
  ui_story_30020602_129_dialog_content = "Oh, tidak... Hiiro! Aku merasakan Eclipsite di kolam itu!",
  ui_story_30020602_130_dialog_content = "<anim type=Shake>Grahhh—!!</anim>",
  ui_story_30020602_131_dialog_content = "... Biarkan aku pergi! Argh—Glub, glub, glub...",
  ui_story_30020602_132_dialog_content = "PlayerName!",
  ui_story_30020602_133_dialog_content = "Kamu monster-monster kotor...",
  ui_story_30020602_134_dialog_content = "Berpencar dan melampaui—!",
  ui_story_30020602_135_dialog_content = "Graah...",
  ui_story_30020602_136_dialog_content = "<color=#e8d9bb>Dengan kecepatan kilat, Hiiro menghunus pedangnya dan mengubah penyerang menjadi debu, tidak meninggalkan tanda keberadaan mereka.</color>",
  ui_story_30020602_137_dialog_content = "<color=#e8d9bb>Pakaian elegannya membuat kehadirannya yang mempesona menjadi lebih indah.</color>",
  ui_story_30020602_138_dialog_content = "<color=#e8d9bb>Namun, dia tidak berniat untuk mempertahankan keindahan momen ini dalam waktu lama.</color>",
  ui_story_30020602_139_dialog_content = "PlayerName! Kau baik-baik saja? Ambil tanganku, cepat!",
  ui_story_30020602_140_dialog_content = "Glub, glub, glub... H-Hiiro...",
  ui_story_30020602_141_option_content = "Ambil tangan Hiiro",
  ui_story_30020602_142_dialog_content = "<anim type=Shake>Grahhh—!!</anim>",
  ui_story_30020602_143_option_content = "Psychic Scan",
  ui_story_30020602_144_dialog_content = "Hiiro... Eclipsite... di belakangmu! Glub, glub, glub...",
  ui_story_30020602_145_dialog_content = "Aduh!",
  ui_story_30020602_146_dialog_content = "<color=#e8d9bb>Plak! Tabok, tabok!</color>",
  ui_story_30020602_147_dialog_content = "Graah...",
  ui_story_30020602_148_dialog_content = "Gan, gan, gan...",
  ui_story_30020602_149_dialog_content = "PlayerName! PlayerName!",
  ui_story_30020602_150_dialog_content = "Jangan khawatir, aku datang!",
  ui_story_30020602_151_dialog_content = "Hat… Hatsyiii!",
  ui_story_30020602_152_dialog_content = "Saya tidak menyangka mereka akan menyeret saya ke dalam air... Saya yakin kali ini saya benar-benar akan mati.",
  ui_story_30020602_153_dialog_content = "Baguslah kau begitu kuat. Berkatmu, aku hanya menelan beberapa tegukan air kolam dan itu saja, haha...",
  ui_story_30020602_154_dialog_content = "Kamu tertawa?",
  ui_story_30020602_155_dialog_content = "M-maaf—!",
  ui_story_30020602_156_dialog_content = "Aku benar-benar memperlambatmu kali ini...",
  ui_story_30020602_157_dialog_content = "Itu bukan yang membuatku kesal... Lupakan saja.",
  ui_story_30020602_158_dialog_content = "Kamu basah kuyup. Dengan keadaan seperti ini, kamu akan segera masuk angin.",
  ui_story_30020602_159_dialog_content = "Tapi kau juga sama.",
  ui_story_30020602_160_dialog_content = "Kita harus menyalakan api dan mengeringkan diri kita. Aku akan pergi mengumpulkan beberapa kayu bakar!",
  ui_story_30020602_161_dialog_content = "...",
  ui_story_30020602_162_dialog_content = "...",
  ui_story_30020602_163_dialog_content = "...",
  ui_story_30020602_164_dialog_content = "...",
  ui_story_30020602_165_dialog_content = "...",
  ui_story_30020602_166_dialog_content = "Aku benar-benar minta maaf tentang hari ini!",
  ui_story_30020602_167_dialog_content = "Kalau saja aku sedikit lebih berhati-hati, kamu juga tidak akan basah—",
  ui_story_30020602_168_dialog_content = "Benar bahwa Anda harus merenungkan kesalahan Anda.",
  ui_story_30020602_169_dialog_content = "Saya! Saya janji!",
  ui_story_30020602_170_dialog_content = "Tidak peduli siapa kamu; dalam pertempuran, prioritas utama semua orang haruslah keselamatan mereka sendiri.",
  ui_story_30020602_171_dialog_content = "Kalau terjadi sesuatu padamu hari ini—",
  ui_story_30020602_172_dialog_content = "... Aku bahkan tidak mau memikirkannya.",
  ui_story_30020602_173_dialog_content = "Hiiro...",
  ui_story_30020602_174_dialog_content = "Sudah lama aku terbiasa melindungi orang lain, tapi kamu adalah orang pertama—",
  ui_story_30020602_175_dialog_content = "...",
  ui_story_30020602_176_dialog_content = "O-Orang pertama?",
  ui_story_30020602_177_dialog_content = "(Orang pertama yang terlalu bodoh untuk melindungi?)",
  ui_story_30020602_178_dialog_content = "Orang pertama yang mencoba melindungiku malah...!",
  ui_story_30020602_179_dialog_content = "Para Eclipsite itu lebih dekat denganmu, dan namun kau malah memperingatkanku daripada mencari perlindungan! Apa yang sebenarnya sedang kau pikirkan?!",
  ui_story_30020602_180_dialog_content = "Aku tidak benar-benar berpikir... Jangan menatapku seperti itu. Itu hanya insting!",
  ui_story_30020602_181_dialog_content = "Insting?",
  ui_story_30020602_182_dialog_content = "... Seperti yang sudah aku katakan, kebaikanmu kadang bisa menakutkan.",
  ui_story_30020602_183_dialog_content = "Tak ada seorang pun yang ingin membayangkan masa depan tanpa kehadiranmu.",
  ui_story_30020602_184_dialog_content = "Untuk bunga mekar dan kemudian layu adalah tatanan alam dunia.",
  ui_story_30020602_185_dialog_content = "Namun, kehilanganmu akan membuat tatanan itu tampak semakin kejam...",
  ui_story_30020602_186_dialog_content = "Hiiro... Maaf. Aku tidak tahu kalau kamu sangat khawatir tentangku.",
  ui_story_30020602_187_dialog_content = "Tapi aku seharusnya tahu.",
  ui_story_30020602_188_dialog_content = "Ketika pertama kali aku merasakan kehadiran Eclipsite, aku langsung teringat padamu. Wajar saja jika kamu juga khawatir dengan keamananku.",
  ui_story_30020602_189_dialog_content = "Aku terlalu ceroboh kali ini.",
  ui_story_30020602_190_dialog_content = "...",
  ui_story_30020602_191_dialog_content = "Baiklah.",
  ui_story_30020602_192_dialog_content = "Apakah menurutmu suku timur juga khawatir tentang dewa gunung saat ini?",
  ui_story_30020602_193_dialog_content = "Aku tidak bisa berbicara atas nama dewa, tetapi selalu ada orang yang peduli tentangmu, baik di masa lalu maupun sekarang.",
  ui_story_30020602_194_dialog_content = "Orang tuamu, gurumu, Granny, Sanki...",
  ui_story_30020602_195_dialog_content = "Dan saya.",
  ui_story_30020602_196_dialog_content = "... May bolehkah aku bertanya sesuatu?",
  ui_story_30020602_197_dialog_content = "Tentu, apa itu?",
  ui_story_30020602_198_dialog_content = "<size=30>Apakah kamu merasakan hal yang sama terhadapku seperti Granny lebih awal hari ini? Apakah kamu berpikir aku... menggemaskan?</size>",
  ui_story_30020602_199_dialog_content = "... Apa tadi? Aku tidak mendengar dengan jelas.",
  ui_story_30020602_200_dialog_content = "Bukan apa-apa. Lupakan.",
  ui_story_30020602_201_dialog_content = "...",
  ui_story_30020602_202_dialog_content = "Ya, kamu dulu menggemaskan.",
  ui_story_30020602_203_dialog_content = "—!",
  ui_story_30020602_204_dialog_content = "Sangat, sebenarnya.",
  ui_story_30020602_205_dialog_content = "<color=#e8d9bb>Cahaya tenang dari api unggun memberikan warna aneh pada wajah Hiiro.</color>",
  ui_story_30020602_206_dialog_content = "<color=#e8d9bb>Mungkin ini adalah warna bunga sakura yang mekar lebih awal di tempat yang jauh, atau warna emosi kuat yang wanita cantik ini terlalu malu untuk ungkapkan.</color>"
}
return config
